function e(){let e=document.querySelectorAll(`.faq__item`);e.length&&e.forEach(t=>{let n=t.querySelector(`.faq__button`);n?.addEventListener(`click`,()=>{let r=t.classList.contains(`faq__item--open`);e.forEach(e=>{e!==t&&(e.classList.remove(`faq__item--open`),e.querySelector(`.faq__button`)?.setAttribute(`aria-expanded`,`false`))}),t.classList.toggle(`faq__item--open`,!r),n.setAttribute(`aria-expanded`,String(!r))})})}document.addEventListener(`DOMContentLoaded`,()=>{e()});